import re
with open('doc/Patient.md', 'r') as f:
    content = f.read()
full = re.sub(r'\n+', ' ', content)

abnormal = ['4634342', '2956679', '2370675', '3150681', '5164396', '2395148', '3174630', '4792459', '2052784', '5117723', '668398', '2275169', '5093771']

results = {}
for pat in abnormal:
    idx = full.lower().find(f'patient {pat.lower()}')
    if idx >= 0:
        snippet = full[idx:idx+800]
        year_m = re.search(r'\b(19|20)\d{2}\b', snippet)
        month_m = re.search(r'(?:born|birthdate)[^\n]*?(January|February|March|April|May|June|July|August|September|October|November|December)', snippet, re.IGNORECASE)
        if year_m and month_m:
            results[pat] = (month_m.group(1), year_m.group(0))
            print(f'{pat}: {month_m.group(1)} {year_m.group(0)}')
        else:
            print(f'{pat}: Not found')

print(f'\nTotal: {len(results)}/{len(abnormal)}')
for p in results:
    print(f'{p}: {results[p]}')

